import java.util.*;

class Solution {
  public String rankTeams(String[] votes) {
    int n = votes[0].length();
    int[][] counts = new int[26][n];
    for (String vote : votes) for (int i = 0; i < n; i++) counts[vote.charAt(i) - 'A'][i]++;
    Character[] teams = new Character[n];
    for (int i = 0; i < n; i++) teams[i] = votes[0].charAt(i);
    Arrays.sort(
        teams,
        (a, b) -> {
          for (int i = 0; i < n; i++)
            if (counts[b - 'A'][i] != counts[a - 'A'][i])
              return counts[b - 'A'][i] - counts[a - 'A'][i];
          return Character.compare(a, b);
        });
    StringBuilder result = new StringBuilder();
    for (char team : teams) result.append(team);
    return result.toString();
  }
}
